import csv
import re
from collections import defaultdict
from datetime import date, datetime, timedelta
from decimal import Decimal, ROUND_HALF_UP

DATASET = "/app/dataset"


def _valid_pesel(pesel: str) -> bool:
    if not re.fullmatch(r"\d{11}", pesel):
        return False
    weights = [1, 3, 7, 9, 1, 3, 7, 9, 1, 3]
    s = sum(int(d) * w for d, w in zip(pesel[:10], weights))
    return (10 - s % 10) % 10 == int(pesel[10])


def _parse_date(value: str):
    try:
        return datetime.strptime(value.strip(), "%Y-%m-%d").date()
    except ValueError:
        return None


def _period_start(year: int, month: int, weekday: int) -> date:
    # First occurrence of `weekday` in the given month.
    d = date(year, month, 1)
    return d + timedelta(days=(weekday - d.weekday()) % 7)


def _billing_period(d: date, weekday: int) -> tuple[int, int]:
    start = _period_start(d.year, d.month, weekday)
    if d >= start:
        return d.year, d.month
    return (d.year - 1, 12) if d.month == 1 else (d.year, d.month - 1)


def answer() -> dict[str, list[int]]:
    with open(f"{DATASET}/employees.csv", newline="", encoding="utf-8") as f:
        rates = {
            r["PESEL"].strip(): Decimal(r["hourly_rate"])
            for r in csv.DictReader(f)
            if _valid_pesel(r["PESEL"].strip())
        }

    with open(f"{DATASET}/tasks.csv", newline="", encoding="utf-8") as f:
        task_pay = {
            int(r["task_id"]): Decimal(r["pay_per_completion"])
            for r in csv.DictReader(f)
        }

    with open(f"{DATASET}/timesheet.csv", newline="", encoding="utf-8") as f:
        rows = list(csv.DictReader(f))

    records = []
    seen = set()
    for r in rows:
        # Exact duplicates (differing only by record id) are counted once.
        key = tuple(r[c].strip() for c in r if c != "id")
        if key in seen:
            continue
        seen.add(key)

        # Records with nonexistent calendar dates (e.g. 2025-04-31) are not
        # part of the employees' accrued salary chain -> excluded.
        d = _parse_date(r["date"])
        if d is None:
            continue

        # Unknown / invalid PESELs cannot be paid (no hourly rate) -> excluded.
        emp = r["employee_id"].strip()
        if emp not in rates:
            continue

        try:
            hours = Decimal(r["hours_worked"])
        except Exception:
            continue
        if hours < 0 or hours > 24:
            continue

        # Task lists may have broken brackets; bonuses are recomputed from the
        # task catalogue, which drops unknown task ids and negative bonuses.
        task_ids = [int(x) for x in re.findall(r"\d+", r["performed_tasks"])]
        bonus = sum((task_pay[t] for t in task_ids if t in task_pay), Decimal(0))

        records.append((emp, d, hours, bonus))

    if not records:
        return {}

    # The billing period starts on the weekday of the dataset's earliest record.
    weekday = min(d for _, d, _, _ in records).weekday()

    totals = defaultdict(lambda: defaultdict(Decimal))
    for emp, d, hours, bonus in records:
        period = _billing_period(d, weekday)
        totals[emp][period] += hours * rates[emp] + bonus

    return {
        emp: [
            int(totals[emp][p].quantize(Decimal(1), rounding=ROUND_HALF_UP))
            for p in sorted(totals[emp])
        ]
        for emp in sorted(totals)
    }


if __name__ == "__main__":
    import json
    with open("/app/answer.json", "w") as f:
        json.dump(answer(), f, default=list)

